def _old_carrier_shape(value, shape, definitions):
    if "$ref" in shape:
        return _old_carrier_shape(value, definitions[shape["$ref"].rsplit("/",1)[1]], definitions)
    kind=shape.get("type")
    if kind=="object":
        if type(value) is not dict or set(value)!=set(shape["properties"]):return False
        return all(_old_carrier_shape(value[key],child,definitions) for key,child in shape["properties"].items())
    if kind=="array":
        if type(value) is not list or not shape.get("minItems",0)<=len(value)<=shape.get("maxItems",65536):return False
        if "prefixItems" in shape:
            return len(value)==len(shape["prefixItems"]) and all(_old_carrier_shape(v,c,definitions) for v,c in zip(value,shape["prefixItems"]))
        return all(_old_carrier_shape(v,shape["items"],definitions) for v in value)
    if kind=="string":
        if type(value) is not str or not shape.get("minLength",0)<=len(value)<=shape.get("maxLength",65536):return False
        if "pattern" in shape and re.search(shape["pattern"],value) is None:return False
    elif kind=="integer":
        if type(value) is not int or not shape.get("minimum",0)<=value<=shape.get("maximum",2**63-1):return False
    else:return False
    return ("const" not in shape or value==shape["const"]) and ("enum" not in shape or value in shape["enum"])


def _probe_evidence(connection):
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate member")
            result[key] = value
        return result

    schemas = {
        "TERMINATE_NATIVE_RUN": "run.terminate-native-evidence/v1",
        "CONTINUE_NATIVE_RUN": "run.continue-native-evidence/v1",
        "TERMINATE_CONTINUED_NATIVE_RUN": "run.terminate-continued-native-evidence/v1",
        "REVISIT_NATIVE_REGION": "run.revisit-native-region-evidence/v1",
        "TERMINATE_REVISITED_NATIVE_RUN": "run.terminate-revisited-native-evidence/v1",
    }
    rows = connection.execute(sa.text("SELECT command_kind, operation_evidence_canonical FROM run_mutation_receipts ORDER BY run_id, resulting_state_version FOR UPDATE"))
    for kind, payload in rows:
        try:
            if type(payload) is not bytes or not payload:
                raise ValueError("invalid carrier")
            decoded = json.loads(payload.decode("utf-8"), object_pairs_hook=unique)
            if type(decoded) is not dict:
                raise ValueError("invalid object")
            canonical = unicodedata.normalize("NFC", json.dumps(decoded, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False)).encode("utf-8")
            if canonical != payload:
                raise ValueError("noncanonical evidence")
            schema = decoded.get("schema")
            if kind in _OLD_LEGACY_SHAPES:
                shape = _OLD_LEGACY_SHAPES[kind]
                if not _old_carrier_shape(decoded, shape, shape.get("$defs", {})):
                    raise ValueError("unclassifiable old evidence")
            elif kind not in schemas or schema != schemas[kind]:
                raise ValueError("unsupported evidence schema")
            if kind in schemas:
                shape=_OLD_EVIDENCE_SHAPES[schema]
                if not _old_carrier_shape(decoded,shape,shape.get("$defs",{})):
                    raise ValueError("malformed old evidence carrier")
            # Closed typed shapes above bind the top-level schema to command_kind
            # and reject new/unknown structural evidence. Opaque keys and IDs
            # may legally contain completion words; they are not discriminators.
        except (TypeError, ValueError, UnicodeError):
            raise RuntimeError(_REFUSAL) from None

def _error(code, cause=None):
    error = RuntimeError("P3.3-S7-4 migration " + code)
    error.__cause__ = cause
    error.__suppress_context__ = True
    return error

def _lost(connection, error=None):
    if connection.closed or connection.invalidated:
        return True
    if isinstance(error, DBAPIError) and error.connection_invalidated:
        return True
    original = error.orig if isinstance(error, DBAPIError) else error
    return (
        original is not None
        and type(original).__module__.startswith("asyncmy")
        and bool(original.args)
        and original.args[0] in (2006, 2013, 2055)
    )

def _discard(connection, selected):
    def record(error):
        if not hasattr(selected, "close_error"):
            selected.close_error = error
        else:
            selected.disposal_errors = getattr(selected, "disposal_errors", ()) + (error,)

    pool_connection = driver = None
    try:
        # Alembic runs this synchronous Connection inside run_sync. Retain both
        # handles before invalidation/detach can erase access to the asyncmy owner;
        # never acquire a replacement through an invalidated Connection.
        if not connection.closed and not connection.invalidated:
            pool_connection = connection.connection
            driver = pool_connection.driver_connection
    except BaseException as error:
        record(error)
    invalidation_failed = False
    try:
        connection.invalidate()
    except BaseException as error:
        invalidation_failed = True
        record(error)
        if pool_connection is not None:
            try:
                # Remove the owner from reusable circulation before trying any
                # physical close, including when that close itself fails.
                pool_connection.detach()
            except BaseException as error:
                record(error)
    if driver is not None:
        try:
            # asyncmy.Connection.close() closes the transport synchronously;
            # adapter.close() instead awaits graceful I/O through the greenlet.
            driver.close()
        except BaseException as error:
            record(error)
    if invalidation_failed and pool_connection is not None:
        try:
            # Invalidate the detached proxy so wrapper close cannot attempt a
            # transaction rollback on the terminated driver. This alone proves
            # neither physical termination nor server-side named-lock release.
            pool_connection.invalidate()
        except BaseException as error:
            record(error)
    try:
        connection.close()
    except BaseException as error:
        record(error)

def _expression(value):
    # MySQL adds redundant parentheses/backticks and character introducers.
    # Parse boolean structure rather than deleting meaningful grouping.
    value = value.replace("\\'", "'")
    value = re.sub(r"(`?[A-Za-z_][A-Za-z_0-9]*`?)\s+REGEXP\s+('(?:''|[^'])*')",
                   r"REGEXP_LIKE(\1,\2)", value, flags=re.IGNORECASE)
    tokens = re.findall(r"'(?:''|[^'])*'|`[^`]*`|[A-Za-z_][A-Za-z_0-9]*|[0-9]+|>=|<=|<>|!=|[^\s]", value)
    tokens = [t if t.startswith("'") else t.strip('`').upper() for t in tokens]
    tokens = [t for t in tokens if t not in ('_ASCII', '_UTF8MB4', '_UTF8MB3', '_UTF8')]
    tokens = ['LENGTH' if t == 'OCTET_LENGTH' else t for t in tokens]
    for index in range(len(tokens)-5,-1,-1):
        if (tokens[index] == '(' and re.fullmatch(r'[A-Z_][A-Z_0-9]*', tokens[index+1])
                and tokens[index+2] in ('+', '-') and tokens[index+3].isdigit() and tokens[index+4] == ')'):
            tokens[index:index+5] = tokens[index+1:index+4]
    def parse(items):
        while items and items[0] == '(':
            depth = 0
            for index, token in enumerate(items):
                depth += (token == '(') - (token == ')')
                if depth == 0: break
            if index != len(items) - 1: break
            items = items[1:-1]
        for separator in ('OR', 'AND'):
            depth = 0; between = False; start = 0; groups = []
            for index, token in enumerate(items):
                depth += (token == '(') - (token == ')')
                if depth: continue
                if token == 'BETWEEN': between = True
                elif token == 'AND' and between: between = False
                elif token == separator:
                    groups.append(parse(items[start:index])); start = index + 1
            if groups:
                groups.append(parse(items[start:]))
                flattened = []
                for group in groups:
                    if group and group[0] == separator: flattened.extend(group[1:])
                    else: flattened.append(group)
                return (separator, *flattened)
        return ('ATOM', *items)
    return parse(tokens)

def _preflight(connection, *, upgrading, expected_revision=None):
    version = connection.execute(sa.text('SELECT version_num FROM alembic_version')).scalar_one()
    if version != (expected_revision or ('20260918_0010' if upgrading else '20260920_0011')):
        raise RuntimeError('Unexpected native Run completion migration starting revision')
    tables = set(connection.execute(sa.text('SHOW TABLES')).scalars())
    expected = {name for name, _ in _CREATE_TABLES}
    if (tables & expected) != (set() if upgrading else expected):
        raise RuntimeError('Partial native Run completion schema requires operator inspection')
    for table, name, old, new in _CONSTRAINTS:
        row = connection.execute(sa.text('SELECT cc.CHECK_CLAUSE, tc.ENFORCED FROM information_schema.CHECK_CONSTRAINTS cc JOIN information_schema.TABLE_CONSTRAINTS tc ON cc.CONSTRAINT_SCHEMA = tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME = tc.CONSTRAINT_NAME WHERE tc.CONSTRAINT_SCHEMA = DATABASE() AND tc.TABLE_NAME = :table AND tc.CONSTRAINT_NAME = :name'), dict(table=table, name=name)).one_or_none()
        if row is None or row[1] != 'YES' or _expression(row[0]) != _expression(old if upgrading else new):
            raise RuntimeError('Unexpected native Run completion CHECK definition or enforcement')
    expected_tables = _TABLES_BEFORE if upgrading else _TABLES_AFTER
    for table, statement in expected_tables:
        columns = connection.execute(sa.text('SELECT COLUMN_NAME, IS_NULLABLE, COLUMN_TYPE, COLUMN_DEFAULT, EXTRA, CHARACTER_SET_NAME, COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :table ORDER BY ORDINAL_POSITION'), dict(table=table)).all()
        expected_columns = re.findall(r'^\s+([a-z_][a-z_0-9]*)\s+', statement, re.MULTILINE)
        if [row[0] for row in columns] != expected_columns or [row[1] for row in columns] != ['NO' if 'NOT NULL' in line else 'YES' for line in re.findall(r'^\s+[a-z_][a-z_0-9]*\s+[^\n]+', statement, re.MULTILINE)]:
            raise RuntimeError('Contradictory native Run completion table requires operator inspection')
        expected_types = [kind.lower().replace('integer','int') for kind in re.findall(r'^\s+[a-z_][a-z_0-9]*\s+([A-Z]+(?:\(\d+\))?)(?=[,\s])', statement, re.MULTILINE)]
        if [row[2] for row in columns] != expected_types or any(row[3] is not None or row[4] for row in columns):
            raise RuntimeError('Contradictory native Run completion column type/default')
        expected_text = {name:(charset,collation) for name,charset,collation in re.findall(
            r'^\s+([a-z_][a-z_0-9]*)\s+VARCHAR\(\d+\) CHARACTER SET ([a-z0-9]+) COLLATE ([a-z0-9_]+)',statement,re.MULTILINE)}
        if any(tuple(row[5:7]) != expected_text.get(row[0],(None,None)) for row in columns):
            raise RuntimeError('Contradictory native Run completion column collation')
        options = connection.execute(sa.text('SELECT ENGINE,TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:table'),dict(table=table)).one()
        if tuple(options) != ('InnoDB','utf8mb4_bin'):
            raise RuntimeError('Contradictory native Run completion engine/collation')
        constraints = connection.execute(sa.text('SELECT CONSTRAINT_NAME,CONSTRAINT_TYPE FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME=:table'),dict(table=table)).all()
        expected_constraints = {'PRIMARY':'PRIMARY KEY'}
        for name,kind in re.findall(r'CONSTRAINT ([a-z_]+) (CHECK|UNIQUE|FOREIGN KEY)',statement):
            expected_constraints[name] = {'CHECK':'CHECK','UNIQUE':'UNIQUE','FOREIGN KEY':'FOREIGN KEY'}[kind]
        if dict(constraints) != expected_constraints:
            raise RuntimeError('Contradictory native Run completion constraint inventory')
        keys = connection.execute(sa.text('SELECT CONSTRAINT_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME=:table ORDER BY CONSTRAINT_NAME,ORDINAL_POSITION'),dict(table=table)).all()
        actual_keys = {}
        for name,column,target,target_column in keys:
            actual_keys.setdefault(name,[]).append((column,target,target_column))
        expected_keys = {'PRIMARY':[(c.strip(),None,None) for c in re.search(r'PRIMARY KEY \(([^)]+)\)',statement).group(1).split(',')]}
        for name,cols in re.findall(r'CONSTRAINT ([a-z_]+) UNIQUE \(([^)]+)\)',statement):
            expected_keys[name]=[(c.strip(),None,None) for c in cols.split(',')]
        for name,cols,target,target_cols in re.findall(r'CONSTRAINT ([a-z_]+) FOREIGN KEY\(([^)]+)\) REFERENCES ([a-z_]+) \(([^)]+)\)',statement):
            expected_keys[name]=[(c.strip(),target,t.strip()) for c,t in zip(cols.split(','),target_cols.split(','),strict=True)]
        if actual_keys != expected_keys:
            raise RuntimeError('Contradictory native Run completion key associations')
        rules=connection.execute(sa.text('SELECT UPDATE_RULE,DELETE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME=:table'),dict(table=table)).all()
        if any(tuple(row) != ('RESTRICT','RESTRICT') for row in rules):
            raise RuntimeError('Contradictory native Run completion foreign-key rules')
        for name, clause in re.findall(r'CONSTRAINT (ck_[a-z_]+) CHECK \(([^\n]+)\)', statement):
            row = connection.execute(sa.text('SELECT cc.CHECK_CLAUSE, tc.ENFORCED FROM information_schema.CHECK_CONSTRAINTS cc JOIN information_schema.TABLE_CONSTRAINTS tc ON cc.CONSTRAINT_SCHEMA = tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME = tc.CONSTRAINT_NAME WHERE tc.CONSTRAINT_SCHEMA = DATABASE() AND tc.TABLE_NAME = :table AND tc.CONSTRAINT_NAME = :name'), dict(table=table, name=name)).one_or_none()
            if row is None or row[1] != 'YES' or _expression(row[0]) != _expression(clause):
                raise RuntimeError(f'Contradictory native Run completion table CHECK: {table}.{name}')

def _amend(*, terminating):
    connection = op.get_bind()
    stage = "BEFORE"
    try:
        if _lost(connection):
            raise _error("ACQUIRE_CONNECTION_LOST_BEFORE")
        if not connection.in_transaction():
            connection.begin()
        owner_connection_id = connection.execute(sa.text("SELECT CONNECTION_ID()")).scalar_one()
        if _lost(connection):
            raise _error("ACQUIRE_CONNECTION_LOST_BEFORE")
        stage = "PENDING"
        result = connection.execute(sa.text(f"SELECT GET_LOCK('{_LOCK}', 30)")).scalar_one()
        if type(result) is int and result == 0:
            raise _error("ACQUIRE_TIMEOUT")
        if result is None:
            raise _error("ACQUIRE_NULL")
        if type(result) is not int or result != 1:
            raise _error("ACQUIRE_INVALID_RESULT")
        stage = "AFTER"
        if _lost(connection):
            raise _error("ACQUIRE_CONNECTION_LOST_AFTER")
    except BaseException as error:
        if type(error) is RuntimeError and str(error).startswith("P3.3-S7-4 migration ACQUIRE_"):
            selected = error
        elif not isinstance(error, Exception):
            selected = error
        elif _lost(connection, error):
            selected = _error("ACQUIRE_CONNECTION_LOST_" + stage, error)
        else:
            selected = _error("ACQUIRE_STATEMENT_FAILED", error)
        if str(selected) != "P3.3-S7-4 migration ACQUIRE_TIMEOUT":
            _discard(connection, selected)
        raise selected

    primary = None
    primary_traceback = None
    observed_loss = None
    stage = "BEFORE_PROBES"
    completed = []
    try:
        _preflight(connection, upgrading=terminating)
        if not terminating:
            for table, predicate in _PROBES:
                stage = "PROBE_" + table
                if _lost(connection):
                    raise _error("BODY_CONNECTION_LOST_" + stage)
                if connection.execute(sa.text(f"SELECT 1 FROM {table} WHERE {predicate} LIMIT 1 FOR UPDATE")).first() is not None:
                    raise RuntimeError(_REFUSAL) from None
        if not terminating:
            stage = "PROBE_CANONICAL_EVIDENCE"
            _probe_evidence(connection)
        for table, name, previous, successor in (_CONSTRAINTS if terminating else reversed(_CONSTRAINTS)):
            stage = "DDL_" + name
            if _lost(connection):
                raise _error("BODY_CONNECTION_LOST_" + stage)
            expression = successor if terminating else previous
            connection.execute(sa.text(f"ALTER TABLE {table} DROP CHECK {name}, ADD CONSTRAINT {name} CHECK ({expression})"))
            completed.append(name)
            if _lost(connection):
                raise _error("BODY_CONNECTION_LOST_AFTER_" + name)
        stage = "AFTER_DDL_PREFLIGHT"
        _preflight(connection, upgrading=not terminating,
                   expected_revision="20260918_0010" if terminating else "20260920_0011")
    except BaseException as error:
        if isinstance(error, Exception) and _lost(connection, error):
            if type(error) is RuntimeError and str(error).startswith("P3.3-S7-4 migration BODY_CONNECTION_LOST_"):
                primary = error
            else:
                observed_loss = error
                primary = _error("BODY_CONNECTION_LOST_" + stage, error)
        else:
            primary = error
        primary.completed_constraints = tuple(completed)
        primary.failed_stage = stage
        primary_traceback = error.__traceback__

    cleanup_error = None
    try:
        if _lost(connection, observed_loss):
            cleanup_error = _error("RELEASE_CONNECTION_LOST_BEFORE", observed_loss)
        else:
            result = connection.execute(sa.text(f"SELECT RELEASE_LOCK('{_LOCK}')")).scalar_one()
            if type(result) is int and result == 1:
                pass
            elif type(result) is int and result == 0:
                cleanup_error = _error("RELEASE_NOT_OWNER")
            elif result is None:
                cleanup_error = _error("RELEASE_NULL")
            else:
                cleanup_error = _error("RELEASE_INVALID_RESULT")
    except BaseException as error:
        if not isinstance(error, Exception):
            cleanup_error = error
        elif _lost(connection, error):
            cleanup_error = _error("RELEASE_CONNECTION_LOST_PENDING", error)
        else:
            cleanup_error = _error("RELEASE_STATEMENT_FAILED", error)
    if cleanup_error is not None:
        _discard(connection, cleanup_error)
    if primary is not None:
        primary.cleanup_error = cleanup_error
        if (stage.startswith(("CREATE_", "DDL_", "DROP_")) or completed) and not connection.closed:
            _discard(connection, primary)
        raise primary.with_traceback(primary_traceback)
    if cleanup_error is not None:
        raise cleanup_error

def upgrade():
    _amend(terminating=True)

def downgrade():
    _amend(terminating=False)
